import{_ as t,o as s,c as a,a2 as d}from"./chunks/framework.D9E58p8B.js";const h=JSON.parse('{"title":"Vue","description":"","frontmatter":{"title":"Vue"},"headers":[],"relativePath":"reference/vue.md","filePath":"reference/vue.md"}'),i={name:"reference/vue.md"};function o(r,e,n,l,c,u){return s(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="vue-voir-l-ecran" tabindex="-1">Vue : voir l&#39;écran <a class="header-anchor" href="#vue-voir-l-ecran" aria-label="Permalink to &quot;Vue : voir l&#39;écran&quot;">​</a></h1><p>Vue est l&#39;organe de perception de l&#39;écran. Il capture, convertit des coordonnées, localise un texte visible et mémorise la topologie de vos écrans. Tous ses outils sont en lecture seule et ne sont pas soumis au plafond des Mains. Vue ne <strong>lit pas</strong> l&#39;écran à votre place : il renvoie des images et des positions, c&#39;est au modèle de les interpréter.</p><table tabindex="0"><thead><tr><th>Outil</th><th>Rôle</th><th>Niveau</th></tr></thead><tbody><tr><td><a href="#vue-displays"><code>vue_displays</code></a></td><td>Lister les écrans actifs</td><td>lecture</td></tr><tr><td><a href="#vue-snapshot"><code>vue_snapshot</code></a></td><td>Capturer un écran (image PNG et contrat de coordonnées)</td><td>lecture</td></tr><tr><td><a href="#vue-resolve"><code>vue_resolve</code></a></td><td>Convertir pixel d&#39;image et point global, sans capturer</td><td>lecture</td></tr><tr><td><a href="#vue-find"><code>vue_find</code></a></td><td>Localiser un libellé visible par OCR</td><td>lecture</td></tr><tr><td><a href="#vue-calibrate"><code>vue_calibrate</code></a></td><td>Enregistrer la topologie d&#39;écrans sous un nom</td><td>lecture</td></tr><tr><td><a href="#vue-profile"><code>vue_profile</code></a></td><td>Lire le profil apparié à l&#39;environnement actuel</td><td>lecture</td></tr><tr><td><a href="#vue-profile-brief"><code>vue_profile_brief</code></a></td><td>Brief d&#39;amorçage pour un sous-agent</td><td>lecture</td></tr><tr><td><a href="#vue-pilot-brief"><code>vue_pilot_brief</code></a></td><td>Paquet de délégation par tâche</td><td>lecture</td></tr></tbody></table><h2 id="erreurs-communes" tabindex="-1">Erreurs communes <a class="header-anchor" href="#erreurs-communes" aria-label="Permalink to &quot;Erreurs communes&quot;">​</a></h2><p>Une erreur de Vue ne plante jamais le serveur : elle revient sous la forme <code>{&quot;error&quot;: &quot;&lt;code&gt;&quot;, &quot;message&quot;: &quot;&lt;détail&gt;&quot;}</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Signification</th></tr></thead><tbody><tr><td><code>permission_denied</code></td><td>Une autorisation système manque (Enregistrement de l&#39;écran)</td></tr><tr><td><code>invalid_arguments</code></td><td>Un argument est invalide</td></tr><tr><td><code>index_out_of_range</code></td><td>L&#39;indice <code>display</code> n&#39;existe pas</td></tr><tr><td><code>capture_failed</code></td><td>La capture a échoué</td></tr><tr><td><code>exclusions_unreadable</code></td><td>Le fichier d&#39;exclusions est cassé ; le message nomme le fichier et la ligne, jamais la valeur fautive</td></tr></tbody></table><p>En cas de doute sur une permission, appelez d&#39;abord <a href="./diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>.</p><h2 id="vue-displays" tabindex="-1">vue_displays <a class="header-anchor" href="#vue-displays" aria-label="Permalink to &quot;vue_displays {#vue-displays}&quot;">​</a></h2><p>Liste tous les écrans actifs. C&#39;est le point de départ : l&#39;indice <code>index</code> renvoyé est la valeur à passer comme <code>display</code> aux autres outils.</p><p><strong>Paramètres</strong> : aucun.</p><p><strong>Retour</strong> : une liste d&#39;objets <code>{index, width, height, is_main, origin: {x, y}, dpi}</code>.</p><p><strong>Exemple d&#39;appel</strong> : <code>vue_displays</code> sans argument.</p><p><strong>Pièges</strong> : l&#39;origine d&#39;un écran secondaire peut être négative dans le bureau global.</p><h2 id="vue-snapshot" tabindex="-1">vue_snapshot <a class="header-anchor" href="#vue-snapshot" aria-label="Permalink to &quot;vue_snapshot {#vue-snapshot}&quot;">​</a></h2><p>Capture un écran et le renvoie sous forme d&#39;image, après censure et expurgation.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>display</code></td><td>entier</td><td><code>0</code></td><td>non</td><td>Indice d&#39;écran, tel que listé par <code>vue_displays</code></td></tr><tr><td><code>max_width</code></td><td>entier</td><td><code>720</code></td><td>non</td><td>Plafond de réduction de l&#39;image servie, en pixels d&#39;image ; <code>0</code> le désactive</td></tr><tr><td><code>region</code></td><td>objet <code>{x, y, width, height}</code></td><td>écran entier</td><td>non</td><td>Sous-région à capturer, en points, locale à l&#39;écran, bornée à l&#39;écran</td></tr></tbody></table><p><strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;display&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1440</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;region&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">800</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p><strong>Retour</strong> : <strong>deux blocs de contenu, dans cet ordre</strong> : (1) un bloc texte contenant le contrat JSON <code>coord_space</code>, (2) un bloc image PNG en base64 (<code>image/png</code>). Tout le <code>coord_space</code> est exprimé en points, l&#39;unité dans laquelle <code>main_click</code> agit ; <code>image_scale</code> est le nombre de pixels d&#39;image servis <strong>par point</strong>. <code>coord_space.region</code> rapporte ce qui a réellement été capturé, et <code>coord_space.secret_rects_available</code> dit si le masquage par champ secret a pu s&#39;exécuter.</p><p><strong>Censure.</strong> Les fenêtres des applications que vous protégez (<code>apps</code>, <code>secret_apps</code> des exclusions) ne sont jamais refusées : elles sont <strong>censurées</strong>, remplacées par un aplat opaque <code>#3A2A5C</code>, comme les zones déclarées et les champs secrets ; le reste de l&#39;écran est servi. Quand une règle existe, le bloc texte porte aussi :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Valeurs</th><th>Sens</th></tr></thead><tbody><tr><td><code>censored</code></td><td>booléen</td><td>Une censure a été appliquée</td></tr><tr><td><code>censored_reason</code></td><td><code>none</code>, <code>zones</code>, <code>unstable</code>, <code>unknown</code></td><td>Raison</td></tr><tr><td><code>censored_rects</code></td><td>liste de <code>{x, y, width, height}</code></td><td>Zones censurées, en points globaux, rognées à la capture</td></tr></tbody></table><p><strong>Erreurs</strong> : voir <a href="#erreurs-communes">Erreurs communes</a>.</p><p><strong>Pièges</strong></p><ul><li>Une zone <code>#3A2A5C</code> est du contenu masqué, pas un écran vide.</li><li>Avec <code>unstable</code> ou <code>unknown</code>, les fenêtres protégées n&#39;ont pas pu être placées, même après une nouvelle capture automatique : <strong>toute</strong> l&#39;image est l&#39;aplat. Réessayez.</li><li>Sous macOS, la barre des menus est aussi censurée tant qu&#39;une application protégée est au premier plan.</li><li>La valeur par défaut de <code>max_width</code> est 720 : demandez davantage pour du détail fin.</li><li>Sous Windows, un point est un pixel physique de l&#39;écran virtuel et <code>backing_scale</code> vaut toujours 1.0.</li><li>Daimon n&#39;interprète pas l&#39;image : regardez-la vous-même.</li></ul><h2 id="vue-resolve" tabindex="-1">vue_resolve <a class="header-anchor" href="#vue-resolve" aria-label="Permalink to &quot;vue_resolve {#vue-resolve}&quot;">​</a></h2><p>Convertit un pixel d&#39;image (vu dans un <code>vue_snapshot</code> de <code>display</code>) en point global, et inversement, <strong>sans capturer</strong>. Utilisez-le plutôt que de calculer vous-même décalage et échelle : un couple résolu est directement cliquable.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>display</code></td><td>entier</td><td><code>0</code></td><td>non</td><td>Indice d&#39;écran</td></tr><tr><td><code>max_width</code></td><td>entier</td><td><code>720</code></td><td>non</td><td>Le même plafond que le snapshot d&#39;origine ; <code>0</code> le désactive</td></tr><tr><td><code>region</code></td><td>objet <code>{x, y, width, height}</code></td><td>écran entier</td><td>non</td><td>La même région que le snapshot, en points, locale à l&#39;écran</td></tr><tr><td><code>image_x</code>, <code>image_y</code></td><td>nombre</td><td>aucun</td><td>non</td><td>Pixel d&#39;image à convertir (les deux ensemble)</td></tr><tr><td><code>global_x</code>, <code>global_y</code></td><td>nombre</td><td>aucun</td><td>non</td><td>Point global à convertir en pixel d&#39;image (les deux ensemble)</td></tr><tr><td><code>source</code></td><td>chaîne</td><td><code>&quot;probe&quot;</code></td><td>non</td><td><code>&quot;probe&quot;</code> lit la géométrie vivante des écrans ; <code>&quot;profile&quot;</code> lit le profil de calibration apparié, avec repli sur <code>probe</code> si aucun ne correspond</td></tr></tbody></table><p><strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;display&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">720</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;image_x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">360</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;image_y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Retour</strong> : <code>{global_x, global_y}</code> si vous passez <code>image_x</code>/<code>image_y</code>, <code>{image_x, image_y}</code> si vous passez <code>global_x</code>/<code>global_y</code>.</p><p><strong>Erreurs</strong> : voir <a href="#erreurs-communes">Erreurs communes</a>.</p><p><strong>Pièges</strong> : <code>max_width</code> et <code>region</code> doivent être identiques à ceux du snapshot, sinon la conversion est fausse.</p><h2 id="vue-find" tabindex="-1">vue_find <a class="header-anchor" href="#vue-find" aria-label="Permalink to &quot;vue_find {#vue-find}&quot;">​</a></h2><p>Repli de Vue : localise un libellé <strong>visible</strong> par OCR sur l&#39;appareil et renvoie des coordonnées globales cliquables, en points. Utile quand <code>touche_tree</code> et <code>touche_probe</code> restent muets (applications Win32 anciennes, dessinées sur mesure, Electron) et qu&#39;il n&#39;y a donc pas d&#39;arbre d&#39;accessibilité à cliquer.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>text</code></td><td>chaîne</td><td>aucun</td><td><strong>oui</strong></td><td>Texte à localiser à l&#39;écran</td></tr><tr><td><code>display</code></td><td>entier</td><td><code>0</code></td><td>non</td><td>Indice d&#39;écran</td></tr><tr><td><code>max_width</code></td><td>entier</td><td><code>720</code></td><td>non</td><td>Plafond de réduction de la capture interne ; <code>0</code> le désactive</td></tr><tr><td><code>region</code></td><td>objet <code>{x, y, width, height}</code></td><td>écran entier</td><td>non</td><td>Sous-région de recherche, en points, locale à l&#39;écran</td></tr><tr><td><code>min_score</code></td><td>nombre</td><td><code>0.6</code></td><td>non</td><td>Score minimal, dans <code>[0, 1]</code>, pour compter un succès</td></tr><tr><td><code>source</code></td><td>chaîne</td><td><code>&quot;probe&quot;</code></td><td>non</td><td><code>&quot;probe&quot;</code> ou <code>&quot;profile&quot;</code>, comme pour <code>vue_resolve</code></td></tr></tbody></table><p><strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Enregistrer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;display&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;min_score&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Retour</strong> : <code>{found, text, score, image_x, image_y, global_x, global_y, candidates}</code>. En cas d&#39;échec, <code>candidates</code> contient les 5 libellés visibles les plus proches. Passez <code>global_x</code> et <code>global_y</code> tels quels à <code>main_click</code> (espace <code>global</code> par défaut).</p><p><strong>Erreurs</strong> : voir <a href="#erreurs-communes">Erreurs communes</a>. Sous Windows, une langue OCR manquante est signalée comme une erreur, jamais comme un échec vide.</p><p><strong>Pièges</strong></p><ul><li>Le moteur est celui du système : Apple Vision sur une build macOS compilée avec <code>--features apple-vision</code>, <code>Windows.Media.Ocr</code> sous Windows. Toute autre build embarque le moteur factice <code>FakeOcr</code> : aucune vraie reconnaissance, toujours un échec.</li><li>L&#39;OCR lit l&#39;image <strong>censurée</strong> : aucun mot touchant une zone censurée n&#39;est renvoyé. Avec une règle d&#39;exclusion, la réponse ajoute <code>censored</code> et <code>censored_reason</code>.</li><li>C&#39;est un localisateur, pas un interprète : il renvoie une position.</li></ul><h2 id="vue-calibrate" tabindex="-1">vue_calibrate <a class="header-anchor" href="#vue-calibrate" aria-label="Permalink to &quot;vue_calibrate {#vue-calibrate}&quot;">​</a></h2><p>Fige la topologie d&#39;écrans actuelle sous un nom (écriture idempotente : même nom, mise à jour) et renvoie le profil enregistré. Un profil permet à <code>vue_resolve</code> et <code>vue_find</code> d&#39;utiliser <code>source=&quot;profile&quot;</code>.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>name</code></td><td>chaîne</td><td>aucun</td><td><strong>oui</strong></td><td>Nom du profil</td></tr></tbody></table><p><strong>Niveau</strong> : lecture (l&#39;outil enregistre un profil de calibration, il n&#39;agit pas sur l&#39;écran).</p><p><strong>Exemple d&#39;appel</strong> : <code>{ &quot;name&quot;: &quot;bureau-deux-ecrans&quot; }</code></p><p><strong>Retour</strong> : le profil enregistré.</p><h2 id="vue-profile" tabindex="-1">vue_profile <a class="header-anchor" href="#vue-profile" aria-label="Permalink to &quot;vue_profile {#vue-profile}&quot;">​</a></h2><p>Indique le profil de calibration apparié à la topologie d&#39;écrans actuelle, ou signale un environnement inconnu avec les noms de profils connus.</p><p><strong>Paramètres</strong> : aucun. <strong>Niveau</strong> : lecture.</p><h2 id="vue-profile-brief" tabindex="-1">vue_profile_brief <a class="header-anchor" href="#vue-profile-brief" aria-label="Permalink to &quot;vue_profile_brief {#vue-profile-brief}&quot;">​</a></h2><p>Produit le brief d&#39;amorçage d&#39;un sous-agent délégué : porte d&#39;appariement du profil et indices d&#39;écrans adressables.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>expected</code></td><td>chaîne</td><td>aucun</td><td>non</td><td>Nom de profil à vérifier</td></tr></tbody></table><p><strong>Niveau</strong> : lecture. <strong>Exemple d&#39;appel</strong> : <code>{ &quot;expected&quot;: &quot;bureau-deux-ecrans&quot; }</code></p><h2 id="vue-pilot-brief" tabindex="-1">vue_pilot_brief <a class="header-anchor" href="#vue-pilot-brief" aria-label="Permalink to &quot;vue_pilot_brief {#vue-pilot-brief}&quot;">​</a></h2><p>Produit le paquet de délégation d&#39;une tâche : une porte go/no-go et un prompt prêt à coller pour un sous-agent, pour l&#39;objectif donné. Aucun appel d&#39;IA n&#39;est fait.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>objective</code></td><td>chaîne</td><td>aucun</td><td><strong>oui</strong></td><td>Objectif de la tâche déléguée</td></tr><tr><td><code>expected</code></td><td>chaîne</td><td>aucun</td><td>non</td><td>Nom de profil attendu</td></tr></tbody></table><p><strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;objective&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Relever le numéro de version affiché dans la fenêtre À propos&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bureau-deux-ecrans&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Pièges</strong> : si la porte n&#39;est pas prête, calibrez d&#39;abord (<code>vue_calibrate</code>) plutôt que de piloter à l&#39;aveugle.</p>',64)])])}const g=t(i,[["render",o]]);export{h as __pageData,g as default};
